    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Penalize new bin creation exponentially as the stream progresses to favor packing
    let new_bin_penalty = if bin_residual == bin_capacity {
        20.0 + (progress * 80.0).powf(1.5)
    } else {
        0.0
    };

    // Reward bins that create "tight" fits, but penalize creating "dead space" (e.g., < 10)
    // which is unlikely to fit future items.
    let fit_efficiency = if post_res_f < 10.0 && post_res_f > 0.0 {
        15.0 // Strong penalty for creating unusable slivers
    } else {
        post_res_f * 0.5
    };

    // Lookahead interaction: if next_item_size is large and current post_residual is small,
    // we are likely to fragment space. Reward bins that leave enough for the next item.
    let lookahead_penalty = if next_item_size > 0 && post_res_f < (next_item_size as f64) {
        (next_item_size as f64 - post_res_f) * 0.8
    } else {
        0.0
    };

    // Favor bins that align with the current global mean to keep residuals uniform
    let uniformity_bonus = (post_res_f - mean_residual).abs() * 0.2;

    // Favor bins that have fewer alternatives to reduce fragmentation (Best-Fit principle)
    let scarcity_bonus = if fitting_bins_count == 1 { -5.0 } else { 0.0 };

    let score = fit_efficiency + new_bin_penalty + lookahead_penalty + uniformity_bonus + scarcity_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left after placement.
    // Minimizing this tends towards Best Fit.
    let mut score = post_res;

    // Penalty for creating "slivers" (very small residuals) that are unlikely to be filled.
    // We penalize residuals in the range [1, 9] as these are too small for most items.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead logic: If the next item is large, we want to reserve space for it.
    // If post_residual is smaller than the next item, we penalize the current choice.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Dynamic thresholding based on stream progress. 
    // As we near the end of the stream, we become more aggressive about filling existing bins
    // to avoid leaving too many partially full bins open.
    let fill_intensity = 1.0 + (progress * 2.0);
    score *= fill_intensity;

    // If this is a new bin (bin_residual == bin_capacity), we add a cost penalty
    // that decays as the number of open bins increases, to prevent excessive fragmentation.
    if bin_residual == bin_capacity {
        let open_penalty = 40.0 / (open_bins_count as f64 + 1.0);
        score += open_penalty;
    }

    // Reward bins that have a post_residual close to the mean_residual of other bins,
    // which helps keep bin states balanced and prevents "outlier" bins.
    let mean_diff = (post_res - mean_residual).abs();
    score += mean_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best-Fit (smaller post_residual is better)
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it often renders the bin useless for future items.
    // We heavily penalize small fragments (1..10) as they are likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If the next item is large, avoid leaving small residuals
    // that won't fit the next item.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post < next_item {
            score += 30.0 * (1.0 - (post / next_item));
        }
    }

    // Stream progression weighting:
    // As we approach the end of the stream, prioritize closing bins (lower post_residual)
    // to avoid leaving many partially filled bins.
    score += (progress * 20.0) * (post / bin_capacity as f64);

    // If this is a new bin candidate (bin_residual == bin_capacity),
    // add a base cost to open it. Only open if existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost to start a new bin, reduced slightly if we have many open bins
        // or if progress is high (to force consolidation).
        score += 25.0 - (open_bins_count as f64 * 0.5);
    }

    // Reward bins that bring the mean residual closer to the next_item_size,
    // encouraging a balanced filling strategy.
    let residual_diff = (mean_residual - post).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space": if the post_residual is too small to fit any expected future items,
    // we penalize it, but scale this penalty based on how far we are in the sequence.
    // If post_residual < 10, it is likely wasted space.
    if post < 10.0 {
        score += (10.0 - post) * 5.0 * (1.0 + progress);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current bin's post_residual is smaller than the next item, we add a penalty
    // proportional to the size of the next item.
    if next_item_size > 0 && post < (next_item_size as f64) {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // Heuristic for opening new bins:
    // If we are early in the stream, be more conservative with opening new bins.
    // If we are late in the stream, opening a new bin is less costly.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // We only pick this if the cost of placing in existing bins is very high.
        // We normalize the cost of opening a new bin by the current mean_residual.
        score = (mean_residual * 0.8) + (1.0 - progress) * 20.0;
    } else {
        // If it's the last chance to fit an item in an existing bin, reduce the score to prioritize it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Non-linear coupling: favor bins that keep the mean_residual of open bins high,
        // preventing the fragmentation of all bins simultaneously.
        score += (post - mean_residual).powi(2) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "fragmented" space that is too small for common items.
    // We penalize residuals that fall into the "unusable" range (below 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If the next item could potentially fit into this bin's 
    // post_residual, we prioritize this bin heavily to keep items together.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Density Balancing: Penalize opening a new bin if other bins exist.
    // If this is a new bin (residual == capacity), add a significant penalty 
    // unless no existing bins can fit the item (fitting_bins_count == 0).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0;
    }

    // 4. Modulo/Fractional alignment: Favor residuals that are multiples of 25.
    // This aligns with common item sizes to minimize wasted space for future items.
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 5. Mean residual pressure: If the current bin is significantly emptier than 
    // the mean, it is a good candidate to fill up, reducing the number of open bins.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 6. Progressive tightening: As we reach the end of the stream, 
    // prioritize packing tighter to avoid leaving stranded bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

