    // 3. New bin thresholding
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual is already quite low (high fragmentation)
        // or if there are no bins that can fit the current item effectively.
        score += 35.0; 
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // 4. Harmonic coupling: favor bins that keep residual near multiples of 25 (1/4 capacity)
        // to maximize future packing density.
        let rem_mod = post_residual % 25;
        score += rem_mod as f64 * 0.2;

        // 5. Penalize creating "isolated" bins if we have many open
        if open_bins_count > 5 && post_residual < 20 {
            score += 15.0;
