    // 6. Progression scaling: as we approach the end of the stream, be more aggressive
    // about filling existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && !is_new_bin {
        score -= 10.0;
    }

    score
}

