pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are likely to become stranded (dead space < 10)
    // We create a non-linear "valley" for post_residual.
    let mut score = post * post * 0.01 + (100.0 - post).exp() * 0.001;

    // Favor bins that align with the next item size (lookahead coupling)
    if next_item_size > 0 {
        let fit_diff = (post as f64 - next_item_size as f64).abs();
        score += fit_diff * 0.5;
    }

    // Dynamic pressure: As the stream progresses, become more aggressive about 
    // packing tightly into existing bins to avoid opening new ones.
    if fitting_bins_count > 0 {
        // If this bin is the last one that can fit the item, give it a significant discount
        if fitting_bins_count == 1 {
            score -= 50.0 * (1.0 - progress);
        }
        // Penalize opening a new bin (bin_residual == bin_capacity) increasingly as stream ends
        if bin_residual == bin_capacity {
            score += 150.0 * progress;
        }
    }

    // Adjust based on how this bin's residual compares to the global average
    // This promotes bin leveling (balancing fill levels across open bins)
    let residual_balance = (post - mean_residual).abs();
    score += residual_balance * 0.2;

    score
}
